changeSet.sql:
ALTER TABLE public.resident ADD COLUMN occupation varchar(200);
ALTER TABLE public.resident ADD COLUMN workplace varchar(300);
CREATE OR REPLACE VIEW tc2_roster.resident AS SELECT roster_id id,hamlet_id,full_name,birth_date,birth_year,birth_date_precision,
    gender,father_name,mother_name,origin,verification_status,version,created_at,updated_at,
    notes,occupation,workplace FROM public.resident;

rollback.sql:
DROP VIEW tc2_roster.resident;
CREATE VIEW tc2_roster.resident AS SELECT roster_id id,hamlet_id,full_name,birth_date,birth_year,birth_date_precision,
    gender,father_name,mother_name,origin,verification_status,version,created_at,updated_at FROM public.resident;
COMMENT ON VIEW tc2_roster.resident IS 'Updatable UUID projection of public.resident; no duplicated storage';
GRANT SELECT,INSERT,UPDATE,DELETE ON tc2_roster.resident TO police_runtime;
ALTER TABLE public.resident DROP COLUMN workplace;
ALTER TABLE public.resident DROP COLUMN occupation;

